INSERT INTO master_energy_cards (energy_id, energy_name, core_essence, archetype_figure, figure_bio, figure_category, figure_bio_verified) VALUES
  ('00', '🧘‍♂️ ผู้ปลีกวิเวก (The Secluded One)', 'ผู้ที่ค้นพบความแข็งแกร่งและปัญญาผ่านการแยกตัวออกจากโลกภายนอก เพื่อสำรวจจักรวาลภายในตนเอง', 'ฤษี', 'ไม่ใช่บุคคลเดียว แต่เป็นชื่อเรียกนักบวช/ผู้แสวงหาความจริงที่ปลีกวิเวกในป่า ปรากฏในตำนานฮินดูและพุทธหลายเรื่อง เชื่อกันว่าฤษีคือผู้ค้นพบมนตร์และความรู้ผ่านการบำเพ็ญตบะอันยาวนาน', 'role_title', false),
  ('01', '🎖️ วีรบุรุษผู้ถูกลืม (The Unsung Hero)', 'ผู้นำที่เปี่ยมด้วยความสามารถและสร้างผลงานที่โดดเด่น แต่กลับไม่ได้รับการยอมรับหรือเครดิตที่คู่ควร', 'นิโคลา เทสลา', 'วิศวกรไฟฟ้าชาวเซอร์เบีย-อเมริกัน (1856-1943) ผู้บุกเบิกระบบไฟฟ้ากระแสสลับที่ใช้กันทั่วโลกทุกวันนี้ มีความคิดล้ำยุคจำนวนมากที่คนร่วมสมัยเข้าใจยาก และมักถูกจดจำในฐานะอัจฉริยะผู้โดดเดี่ยว', 'historical', false),
  ('02', '💔 คนใจอ่อน (The Soft-Hearted)', 'ผู้ที่ขับเคลื่อนด้วยความเมตตาสงสาร มีความเห็นอกเห็นใจสูง แต่ก็เปราะบางทางอารมณ์และอ่อนไหวต่อความทุกข์ของผู้อื่น', 'พระนางซีตา', 'ตัวละครหลักในมหากาพย์รามายณะของอินเดีย ชายาของพระราม ถูกลักพาตัวโดยทศกัณฐ์ เป็นสัญลักษณ์ของความซื่อสัตย์และความอดทนในวัฒนธรรมฮินดู', 'legendary', false),
  ('03', '😠 อัจฉริยะหัวร้อน (The Hot-headed Genius)', 'ผู้ที่มีสติปัญญาเฉียบแหลมและมีความคิดที่ก้าวล้ำ แต่ถูกบดบังด้วยอารมณ์ที่รุนแรงและความใจร้อน', 'ไมเคิล แองเจลโล(Michelangelo)', 'ศิลปินยุคเรอเนสซองส์ชาวอิตาลี (1475-1564) ผู้วาดเพดานโบสถ์ซิสทีนและปั้นรูปแกะสลัก David เป็นตัวอย่างของอัจฉริยะที่ทุ่มเทให้งานศิลปะจนแทบไม่สนใจชีวิตส่วนตัว', 'historical', false),
  ('04', '🕵️ นักสืบหาความลับ (The Secret Investigator)', 'ผู้ที่เกิดมาพร้อมกับสัญชาตญาณในการสืบเสาะหาความจริง มีความสามารถในการมองเห็นสิ่งที่ซ่อนเร้นและเปิดเผยความลับ', 'เอดการ์ อัลลัน โพ (Edgar Allan Poe)', 'นักเขียนชาวอเมริกัน (1809-1849) บิดาแห่งเรื่องสั้นแนวสยองขวัญและนักสืบสมัยใหม่ ชีวิตเต็มไปด้วยความสูญเสียและความยากลำบาก ซึ่งสะท้อนอยู่ในงานเขียนที่ลึกลับมืดหม่นของเขา', 'historical', false),
  ('05', '🚶‍♂️ นักเดินทางผู้มีเหตุผล (The Rational Traveler)', 'ผู้ที่ใช้ชีวิตผ่านการเดินทางและการเรียนรู้ โดยมีเหตุผลและความเชื่อมั่นในตนเองเป็นเข็มทิศนำทาง', 'โอดิสสิอุส', 'วีรบุรุษในมหากาพย์กรีกโบราณเรื่อง Odyssey ของโฮเมอร์ ขึ้นชื่อเรื่องไหวพริบและกลอุบาย (เช่นม้าไม้เมืองทรอย) ต้องเดินทางกลับบ้านนานถึง 10 ปีหลังสงครามทรอยจบลง', 'mythological', false),
  ('06', '🎭 คนเจ้าเสน่ห์ผู้ผิดหวัง (The Disappointed Charmer)', 'ผู้ที่มีเสน่ห์ดึงดูดใจผู้คนอย่างเป็นธรรมชาติ แต่กลับต้องเผชิญกับความผิดหวังในเรื่องความรักและการเงินอยู่เสมอ', 'มาร์ค แอนโทนี (Mark Antony)', 'แม่ทัพและนักการเมืองโรมัน (83-30 ปีก่อนคริสตกาล) พันธมิตรคนสำคัญของจูเลียส ซีซาร์ และเป็นที่รู้จักจากความรักอันโด่งดังกับคลีโอพัตราแห่งอียิปต์ ก่อนพ่ายแพ้ในสงครามกลางเมืองและจบชีวิตตนเอง', 'historical', false),
  ('07', '💪 นักสู้ผู้ฝ่าฟัน (The Struggling Fighter)', 'ผู้ที่ถูกลิขิตให้ชีวิตต้องเผชิญหน้ากับอุปสรรคและความท้าทายอย่างต่อเนื่อง แต่ก็มีความแข็งแกร่งที่จะต่อสู้และก้าวข้ามไปได้', 'เฮอร์คิวลิส', 'วีรบุรุษที่แข็งแกร่งที่สุดในเทพปกรณัมกรีก บุตรของเทพซุส ต้องทำภารกิจอันโหดหิน 12 ประการ (Twelve Labors) เพื่อไถ่บาป เป็นสัญลักษณ์ของพลังและความอดทนสุดขีด', 'mythological', false),
  ('08', '🎲 นักเสี่ยงโชค (The Gambler)', 'ผู้ที่รักความตื่นเต้นและกล้าได้กล้าเสีย มีความสุขกับการใช้ชีวิตบนความเสี่ยงเพื่อผลตอบแทนที่ยิ่งใหญ่', 'จาโกโม คาสโนวา (Giacomo Casanova)', 'นักผจญภัยและนักเขียนชาวเวนิส (1725-1798) มีชีวิตที่หลากหลายทั้งนักการทูต นักการพนัน และคนรัก ชื่อของเขากลายเป็นคำสามัญที่หมายถึง ''ชายเจ้าชู้'' ในภาษาหลายภาษาจนถึงทุกวันนี้', 'historical', false),
  ('09', '🔮 ผู้มีญาณทิพย์ (The Clairvoyant)', 'ผู้ที่มีสัมผัสที่หกและสัญชาตญาณที่เฉียบคม สามารถเชื่อมต่อกับโลกที่มองไม่เห็นและรับรู้ถึงพลังงานลี้ลับ', 'เทพีไพเธีย', 'ไม่ใช่บุคคลเดียว แต่เป็น ''ตำแหน่ง'' นักบวชหญิงประจำวิหารอพอลโลที่เดลฟี ประเทศกรีซ ผู้ทำหน้าที่เป็นปากเสียงคำทำนายจากเทพอพอลโลตั้งแต่ราว 800 ปีก่อนคริสตกาล จนถึง ค.ศ. 393 มีหลายคนหมุนเวียนทำหน้าที่นี้ตลอดพันกว่าปี', 'role_title', true),
  ('10', '🚀 ผู้ริเริ่มแห่งความสำเร็จ (The Successful Initiator)', 'ผู้นำที่สมบูรณ์แบบซึ่งยืนอยู่ ณ จุดเริ่มต้นใหม่ที่เต็มไปด้วยโอกาสและความสำเร็จ เป็นผู้ที่สามารถเปลี่ยนวิสัยทัศน์ให้กลายเป็นความจริง', 'อเล็กซานเดอร์มหาราช', 'กษัตริย์แห่งมาซิโดเนีย (356-323 ปีก่อนคริสตกาล) ผู้พิชิตดินแดนกว้างใหญ่ตั้งแต่กรีซจรดอินเดียก่อนอายุ 30 ปี ไม่เคยแพ้สงครามแม้แต่ครั้งเดียวตลอดชีวิต', 'historical', false),
  ('11', '🌀 ผู้มีลางสังหรณ์ (The Premonitioner)', 'ผู้ที่มีพลังแห่งสัญชาตญาณและการหยั่งรู้ที่เฉียบคมเป็นสองเท่า สามารถสร้างแรงบันดาลใจและมองเห็นในสิ่งที่คนอื่นมองไม่เห็น', 'โจนออฟอาร์ค', 'หญิงชาวฝรั่งเศส (1412-1431) ผู้อ้างว่าได้รับสัญญาณจากพระเจ้าให้นำทัพฝรั่งเศสต่อสู้กับอังกฤษในสงครามร้อยปี ถูกจับและเผาทั้งเป็นข้อหาศาสนา ต่อมาได้รับการยกย่องเป็นนักบุญ', 'historical', false),
  ('12', '🥀 ศิลปินผู้เปราะบาง (The Fragile Artist)', 'ผู้ที่เรียนรู้และเติบโตผ่านประสบการณ์ มีความสามารถในการปรับตัวและสร้างสมดุลในสถานการณ์ที่ขัดแย้ง', 'วินเซนต์ แวนโกะ', 'จิตรกรชาวดัตช์ (1853-1890) ผู้สร้างผลงานเอกอย่าง Starry Night แต่ขายภาพได้เพียงภาพเดียวขณะมีชีวิต ต่อสู้กับปัญหาสุขภาพจิตตลอดชีวิตก่อนจะเสียชีวิตด้วยวัย 37 ปี', 'historical', false),
  ('13', '🎤 นักพูดผู้สร้างสรรค์ (The Creative Orator)', 'ผู้ที่ต้องเผชิญหน้ากับการเปลี่ยนแปลงครั้งใหญ่ที่ไม่คาดคิด เพื่อรื้อถอนโครงสร้างเก่าและสร้างสรรค์สิ่งใหม่ที่ดีกว่าเดิม', 'Georges Danton', 'นักปฏิวัติฝรั่งเศส (1759-1794) หนึ่งในผู้นำคนสำคัญช่วงต้นของการปฏิวัติฝรั่งเศส มีวาทศิลป์เร่าร้อน แต่ภายหลังถูกอดีตพันธมิตรกล่าวหาและถูกประหารด้วยกิโยตินเช่นเดียวกับที่เขาเคยส่งคนอื่นไป', 'historical', false),
  ('14', '🌐 นักสื่อสารยุคใหม่ (The Modern Communicator)', 'ผู้รักอิสระที่ต้องเรียนรู้ที่จะควบคุมตนเองและจัดการความเสี่ยง เพื่อไม่ให้หลงทางไปกับสิ่งยั่วยุทางโลก', 'เฮอร์มีส', 'เทพผู้สื่อสารในเทพปกรณัมกรีก บุตรของซุส ทำหน้าที่นำสารระหว่างเทพกับมนุษย์ ขึ้นชื่อเรื่องความเฉลียวฉลาด รวดเร็ว และเจ้าเล่ห์ เป็นเทพแห่งการค้าและนักเดินทางด้วย', 'mythological', false),
  ('15', '✈️ นักเดินทางผู้มีเป้าหมาย (The Purposeful Traveler)', 'ผู้มีเสน่ห์ดึงดูดและปัญญาลึกซึ้ง ให้ความสำคัญกับความรัก ครอบครัว และการช่วยเหลือผู้อื่น', 'ไอเนียส (Aeneas)', 'วีรบุรุษในมหากาพย์ Aeneid ของกวีโรมัน Virgil หนีจากเมืองทรอยที่ถูกทำลาย เดินทางข้ามทะเลจนไปตั้งรกรากในอิตาลี ถือเป็นบรรพบุรุษในตำนานของชาวโรมัน', 'mythological', false),
  ('16', '🏡 ผู้สร้างครอบครัว (The Family Builder)', 'ผู้ที่ต้องเผชิญกับการสูญเสียและความผิดหวัง เพื่อนำไปสู่การทบทวนตนเองและการเติบโตทางจิตวิญญาณ', 'โจคาสตา (Jocasta)', 'ตัวละครในตำนานกรีก ราชินีแห่งธีบส์ มารดา (และภายหลังกลายเป็นภรรยาโดยไม่รู้ตัว) ของโออีดิปุส เมื่อความจริงเปิดเผย นางจบชีวิตตนเองด้วยความสิ้นหวัง เป็นสัญลักษณ์ของโศกนาฏกรรมที่หนีไม่พ้นชะตากรรม', 'mythological', false),
  ('17', '🧠 นักปราชญ์ (The Sage)', 'ผู้ที่มีความมั่นใจและพลังงานสูง สามารถทำงานใหญ่ให้สำเร็จได้ด้วยการผสมผสานระหว่างความกล้าหาญและสติปัญญา', 'กษัตริย์โซโลมอน (King Solomon)', 'กษัตริย์แห่งอิสราเอลโบราณ ปรากฏในคัมภีร์ไบเบิลว่าเป็นผู้ทรงปัญญาที่สุด ขึ้นชื่อจากการตัดสินคดีความอันชาญฉลาด (เช่นคดีแม่สองคนแย่งลูก) และการสร้างวิหารแห่งเยรูซาเล็ม', 'religious', false),
  ('18', '🌋 ผู้กล้าบ้าบิ่น (The Daredevil)', 'ผู้ที่ต้องเรียนรู้บทเรียนเรื่องการใช้อำนาจและการควบคุมอารมณ์ เพื่อก้าวข้ามความขัดแย้งและรู้จักการให้อภัย', 'อะคิลลีส', 'นักรบที่เก่งกาจที่สุดในมหากาพย์ Iliad ของโฮเมอร์ แม่จุ่มตัวเขาในแม่น้ำสติกซ์ให้อยู่ยงคงกระพันทั้งตัว ยกเว้นส้นเท้าที่จับไว้ จุดอ่อนเดียวที่ทำให้เขาเสียชีวิตในสงครามทรอย ที่มาของคำว่า Achilles heel', 'mythological', false),
  ('19', '✨ ผู้มีเมตตา (The Benevolent)', 'ผู้นำที่มีวิสัยทัศน์และต้องพึ่งพาตนเองเพื่อสร้างชื่อเสียงและความสำเร็จ ซึ่งมักจะได้รับโชคจากแดนไกล', 'พระเจ้าอโศกมหาราช', 'จักรพรรดิแห่งราชวงศ์เมารยะของอินเดีย (ครองราชย์ 268-232 ปีก่อนคริสตกาล) หลังทำสงครามนองเลือดจนพิชิตแคว้นกลิงคะ พระองค์สำนึกผิดและหันมานับถือพุทธศาสนา เผยแผ่ธรรมะไปทั่วอนุทวีปอินเดีย', 'historical', false),
  ('20', '🧩 ผู้ประสานงาน (The Coordinator)', 'ผู้ที่แสวงหาความสมดุลและความร่วมมือ มีความสามารถในการสร้างความสัมพันธ์ใหม่ๆ แต่ก็อาจลังเลและต้องพึ่งพาผู้อื่น', 'Psyche (ไซคี)', 'มนุษย์หญิงในตำนานกรีกที่งดงามจนเทพีอโฟรไดท์อิจฉา ต้องผ่านบททดสอบยากลำบากหลายอย่างเพื่อพิสูจน์รักแท้กับเทพคิวปิด ท้ายที่สุดได้กลายเป็นอมตะ ชื่อของนางเป็นที่มาของคำว่า psyche หรือจิตวิญญาณ', 'mythological', false),
  ('21', '🌟 ดาวเด่น (The Shining Star)', 'ผู้ที่มีพลังแห่งการแสดงออก ความคิดสร้างสรรค์ และการสื่อสาร สามารถสร้างความสุขและแรงบันดาลใจให้ผู้อื่น', 'เทพอพอลโล', 'เทพแห่งดวงอาทิตย์ ดนตรี บทกวี และคำทำนายในเทพปกรณัมกรีก เป็นเจ้าของวิหารที่เดลฟีซึ่งเป็นที่ตั้งของออราเคิลอันโด่งดัง ถือเป็นเทพที่หล่อเหลาและมีความสามารถรอบด้านที่สุดองค์หนึ่ง', 'mythological', false),
  ('22', '🌪️ ผู้เปลี่ยนแปลงโลก (The World Changer)', 'ผู้ที่มีพลังในการสร้างสรรค์ที่ยิ่งใหญ่ มีเสน่ห์ อ่อนโยน และสามารถสร้างความสำเร็จที่จับต้องได้ โดยเฉพาะงานที่เกี่ยวกับศิลปะและความงาม', 'ลีโอนาร์โด ดา วินชี', 'ศิลปินและนักประดิษฐ์ยุคเรอเนสซองส์ชาวอิตาลี (1452-1519) ผู้วาดภาพ Mona Lisa และ The Last Supper พร้อมร่างแบบเครื่องบิน เฮลิคอปเตอร์ และกายวิภาคมนุษย์ล้ำยุคไปหลายร้อยปี', 'historical', false),
  ('23', '💖 ผู้มีเสน่ห์ (The Charmer)', 'ผู้รักการผจญภัยและการเปลี่ยนแปลง มีความสามารถในการสื่อสารและปรับตัวเข้ากับสิ่งใหม่ๆ ได้อย่างยอดเยี่ยม', 'Cleopatra', 'ฟาโรห์องค์สุดท้ายแห่งอียิปต์โบราณ (69-30 ปีก่อนคริสตกาล) ขึ้นชื่อเรื่องสติปัญญา ไหวพริบทางการเมือง และความสัมพันธ์กับจูเลียส ซีซาร์และมาร์ค แอนโทนี พยายามรักษาเอกราชของอียิปต์จากโรมจนวาระสุดท้าย', 'historical', false),
  ('24', '🛠️ นักปฏิบัติ (The Practitioner)', 'ผู้ที่มีเมตตามหานิยม ให้ความสำคัญกับความรับผิดชอบ ครอบครัว และการดูแลผู้อื่น สามารถสร้างความมั่นคงและหาเงินเก่ง', 'เทพีเดเมเทอร์', 'เทพีแห่งการเกษตรและความอุดมสมบูรณ์ในเทพปกรณัมกรีก เมื่อลูกสาวเพอร์เซโฟนีถูกลักพาตัวไปยังยมโลก นางโศกเศร้าจนพืชพันธุ์ทั่วโลกเหี่ยวเฉา กลายเป็นที่มาของตำนานฤดูกาล', 'mythological', false),
  ('25', '🎓 นักวิชาการ (The Scholar)', 'ผู้ที่แสวงหาความจริงผ่านการวิเคราะห์และการค้นคว้า มีจิตวิญญาณที่ลึกซึ้ง และมักได้รับการสนับสนุนจากสตรี', 'Peter Abelard', 'นักปรัชญาและนักเทววิทยาชาวฝรั่งเศส (1079-1142) มีชื่อเสียงด้านตรรกศาสตร์ และเป็นที่จดจำจากความรักต้องห้ามกับเอโลอีส ลูกศิษย์ของตน ซึ่งจบลงด้วยโศกนาฏกรรม', 'historical', false),
  ('26', '⚖️ ผู้พิพากษา (The Judge)', 'ผู้ที่มีอำนาจในการจัดการธุรกิจและการเงิน สามารถสร้างความสำเร็จและความมั่นคงได้ด้วยวาจาที่เป็นทรัพย์', 'เทพพลูตอส (Plutus)', 'เทพแห่งความมั่งคั่งในเทพปกรณัมกรีก ตามตำนานถูกเทพซุสทำให้ตาบอดเพื่อแจกจ่ายทรัพย์สมบัติอย่างไม่เลือกที่รักมักที่ชัง ไม่ใช่ให้เฉพาะคนดีเท่านั้น', 'mythological', false),
  ('27', '🙏 ผู้เสียสละ (The Altruist)', 'ผู้ที่ทำงานเพื่อมนุษยธรรม มีความเสียสละ แต่ก็ต้องเผชิญกับปัญหาการเงินและความรัก', 'เจ้าชายมิชกิน (Prince Myshkin)', 'ไม่ใช่บุคคลจริง แต่เป็นตัวละครเอกในนิยาย The Idiot (1869) ของฟีโอดอร์ ดอสโตเยฟสกี นักเขียนรัสเซีย เป็นชายผู้มีจิตใจบริสุทธิ์และซื่อสัตย์เกินกว่าสังคมจะเข้าใจ จนถูกมองว่าบ้า', 'fictional', true),
  ('28', '🦁 ผู้นำที่กล้าหาญ (The Courageous Leader)', 'ผู้นำที่แข็งแกร่งในด้านการเงินและการจัดการ สามารถสร้างความสำเร็จที่ยิ่งใหญ่และยั่งยืนได้', 'ลอเรนโซ เดอ เมดิชี (Lorenzo de'' Medici)', 'ผู้ปกครองเมืองฟลอเรนซ์ (1449-1492) ในยุคทองของเรอเนสซองส์อิตาลี ได้รับฉายา Lorenzo ผู้ยิ่งใหญ่ จากการอุปถัมภ์ศิลปินและนักคิดระดับตำนานอย่างมิเคลันเจโลและบอตติเชลลี', 'historical', false),
  ('29', '🙏 ผู้ศรัทธาที่เมตตา (The Merciful Believer)', 'ผู้มีญาณหยั่งรู้และความสามารถทางศิลปะ ใช้ความอ่อนไหวของตนเองในการให้คำปรึกษาและช่วยเหลือผู้อื่น', 'พระถังซัมจั๋ง', 'อ้างอิงจากพระภิกษุจีนตัวจริงชื่อ เสวียนจั้ง (Xuanzang, ค.ศ. 602-664) ผู้เดินทางไปอินเดียเพื่อศึกษาและนำพระคัมภีร์พุทธศาสนากลับมาแปล เรื่องราวการเดินทางถูกแต่งเติมเป็นวรรณกรรมดัง ไซอิ๋ว ในภายหลัง', 'historical', false),
  ('30', '💡 นักคิดนักพูด (The Thinker-Speaker)', 'ผู้ที่มีความคิดสร้างสรรค์และการสื่อสารที่สมบูรณ์แบบ สามารถสร้างผลงานที่ยิ่งใหญ่และมีความสุขในชีวิต', 'Oscar Wilde', 'นักเขียนและกวีชาวไอริช (1854-1900) ขึ้นชื่อเรื่องไหวพริบเฉียบคมและบทสนทนาแสบสัน ผลงานเด่นคือ The Picture of Dorian Gray ชีวิตในบั้นปลายพลิกผันจากคดีอื้อฉาวจนต้องโทษจำคุก', 'historical', false),
  ('31', '👑 ราชาผู้สร้างสรรค์ (The Creative King)', 'ผู้นำที่เริ่มต้นโครงการสร้างสรรค์ด้วยการสื่อสารที่ชัดเจน แต่ชีวิตมักมีการเปลี่ยนแปลงอย่างฉับพลัน', 'กษัตริย์อาเธอร์', 'กษัตริย์ในตำนานของอังกฤษ ผู้นำอัศวินโต๊ะกลมและครอบครองดาบวิเศษเอ็กซ์คาลิเบอร์ แม้ไม่มีหลักฐานประวัติศาสตร์ยืนยันตัวตนจริง แต่ตำนานของเขาเป็นสัญลักษณ์ของความยุติธรรมและอัศวินภาพมาหลายศตวรรษ', 'legendary', false),
  ('32', '💖 ทูตสันถวไมตรี (The Goodwill Ambassador)', 'ผู้มีเสน่ห์และกล้าหาญ สามารถทำงานร่วมกับผู้อื่นเพื่อสร้างสรรค์สิ่งใหม่ๆ และมักมีรายได้ที่ดีมาก', 'เซอร์ แลนสล็อต (Sir Lancelot)', 'อัศวินที่เก่งกาจที่สุดในตำนานโต๊ะกลมของกษัตริย์อาเธอร์ แต่ความรักต้องห้ามกับราชินีกวินิเวียร์นำไปสู่ความแตกแยกและการล่มสลายของอาณาจักรคาเมล็อตในที่สุด', 'legendary', false),
  ('33', '✨ ปรมาจารย์ผู้เมตตา (The Compassionate Master)', 'นักสู้ตัวจริงที่มีความแข็งแกร่ง กล้าหาญ และจริงจังกับชีวิต แต่ก็อาจทำให้หาคู่ครองได้ยาก', 'โมเสส (Moses)', 'ศาสดาสำคัญในศาสนายิว คริสต์ และอิสลาม ตามคัมภีร์เล่าว่าท่านนำชาวอิสราเอลออกจากการเป็นทาสในอียิปต์ และรับบัญญัติสิบประการจากพระเจ้าบนภูเขาซีนาย', 'religious', false),
  ('34', '⚔️ นักรบผู้ชาญฉลาด (The Wise Warrior)', 'ผู้ที่สร้างรากฐานที่มั่นคงผ่านการสื่อสารที่ตรงไปตรงมาและการทำงานหนัก แต่ก็อาจนำไปสู่ความขัดแย้ง', 'เทพีอาธีนา', 'เทพีแห่งปัญญาและสงครามที่มีกลยุทธ์ในเทพปกรณัมกรีก กำเนิดจากศีรษะของเทพซุสโดยตรง เป็นเทพผู้อุปถัมภ์กรุงเอเธนส์ ขึ้นชื่อเรื่องความเฉลียวฉลาดมากกว่าพละกำลัง', 'mythological', false),
  ('35', '🗺️ นักสำรวจ (The Adventurer)', 'ผู้มีอำนาจและบารมี รักการผจญภัยและการเปลี่ยนแปลง มักได้รับการอุปถัมภ์จากผู้ใหญ่', 'คริสโตเฟอร์ โคลัมบัส', 'นักเดินเรือชาวอิตาลี (1451-1506) ผู้นำคณะสำรวจข้ามมหาสมุทรแอตแลนติกจนไปถึงทวีปอเมริกาในปี 1492 แม้จริงๆ ตั้งใจจะหาเส้นทางไปเอเชีย เหตุการณ์นี้เปลี่ยนประวัติศาสตร์โลกไปตลอดกาล', 'historical', false),
  ('36', '💝 ผู้ให้ (The Giver)', 'ผู้ที่มีเสน่ห์เป็นทรัพย์ สามารถใช้การเจรจาเพื่อสร้างความสำเร็จ ให้ความสำคัญกับครอบครัวและความสามัคคี', 'Abigail Adams', 'สุภาพสตรีหมายเลขหนึ่งคนที่สองของสหรัฐฯ (1744-1818) ภรรยาประธานาธิบดีจอห์น อดัมส์ เป็นที่จดจำจากจดหมายนับพันฉบับที่แสดงวิสัยทัศน์ทางการเมืองอันเฉียบคม และเรียกร้องสิทธิสตรีตั้งแต่ยุคก่อตั้งประเทศ', 'historical', false),
  ('37', '📖 นักปราชญ์ผู้สันโดษ (The Solitary Scholar)', 'ผู้ที่ต้องเผชิญกับความลำบากและอุปสรรค เพื่อนำไปสู่การพัฒนาตนเองและการค้นพบทางจิตวิญญาณ', 'ขงจื๊อ', 'นักปรัชญาจีนโบราณ (551-479 ปีก่อนคริสตกาล) ผู้วางรากฐานจริยธรรมและการปกครองที่มีอิทธิพลต่อเอเชียตะวันออกมานานกว่า 2,000 ปี เน้นเรื่องความกตัญญู มารยาท และการปกครองด้วยคุณธรรม', 'historical', false),
  ('38', '💼 นักธุรกิจผู้กล้าได้กล้าเสีย (The Risk-Taking Businessman)', 'ผู้ที่รักความครึกครื้นและงานรื่นเริง สามารถใช้การสื่อสารเพื่อสร้างความสำเร็จทางธุรกิจ แต่ต้องระวังเรื่องการใช้เงิน', 'โฮเวิร์ด ฮิวส์', 'นักธุรกิจ นักบิน และผู้สร้างภาพยนตร์ชาวอเมริกัน (1905-1976) หนึ่งในคนรวยที่สุดในโลกยุคนั้น แต่บั้นปลายชีวิตกลายเป็นคนสันโดษที่ทุกข์ทรมานจากโรคย้ำคิดย้ำทำอย่างรุนแรง', 'historical', false),
  ('39', '🌟 ผู้ใจบุญ (The Philanthropist)', 'ผู้ที่ใช้การสื่อสารเพื่อช่วยเหลือผู้อื่นและสร้างแรงบันดาลใจ สามารถเอาชนะการแข่งขันและมีชื่อเสียง แต่ก็อาจเจอกับทุกขลาภ', 'แอนดรูว์ คาร์เนกี', 'นักอุตสาหกรรมเหล็กกล้าชาวสก็อต-อเมริกัน (1835-1919) จากเด็กยากจนสู่หนึ่งในคนรวยที่สุดในประวัติศาสตร์ ก่อนบริจาคทรัพย์สินเกือบทั้งหมดเพื่อสร้างห้องสมุดและมูลนิธิการกุศลทั่วโลก', 'historical', false),
  ('40', '🔬 นักวิทยาศาสตร์ (The Scientist)', 'การสร้างรากฐานที่ยั่งยืนผ่านการค้นคว้าหาความจริงและนวัตกรรม', 'มารี คูรี', 'นักวิทยาศาสตร์ชาวโปแลนด์-ฝรั่งเศส (1867-1934) ผู้ค้นพบธาตุเรเดียมและโพโลเนียม เป็นผู้หญิงคนแรกที่ได้รับรางวัลโนเบล และเป็นคนเดียวที่ได้รับรางวัลโนเบลถึง 2 สาขาต่างกัน (ฟิสิกส์และเคมี)', 'historical', false),
  ('41', '🏛️ ผู้นำผู้สร้างสรรค์ (The Creative Founder)', 'การเป็นผู้นำที่มั่นคงและน่าเชื่อถือในการริเริ่มสิ่งใหม่', 'Henry Ford', 'ผู้ก่อตั้งบริษัทฟอร์ด มอเตอร์ (1863-1947) ผู้ปฏิวัติการผลิตรถยนต์ด้วยสายพานลำเลียง ทำให้รถยนต์ราคาถูกลงจนคนทั่วไปเป็นเจ้าของได้ เปลี่ยนวิถีชีวิตคนอเมริกันไปตลอดกาล', 'historical', false),
  ('42', '🤝 หุ้นส่วนผู้ภักดี (The Loyal Partner)', 'การสร้างความสมดุลและความร่วมมือที่มั่นคงและมีระเบียบ', 'เทพฮิฟีสตัส (Hephaestus)', 'เทพแห่งการช่างและไฟในเทพปกรณัมกรีก ขาพิการแต่มีฝีมือเป็นเลิศในการตีเหล็กและสร้างสรรค์สิ่งประดิษฐ์ ทำงานอยู่ในโรงตีเหล็กใต้ภูเขาไฟ เป็นเทพที่ขยันที่สุดในบรรดาเทพโอลิมปัส', 'mythological', false),
  ('43', '📢 นักสื่อสารผู้หนักแน่น (The Firm Communicator)', 'การสร้างสรรค์ผลงานที่มีคุณภาพผ่านการสื่อสารที่ชัดเจน', 'วินสตัน เชอร์ชิลล์', 'นายกรัฐมนตรีอังกฤษ (1874-1965) ผู้นำสหราชอาณาจักรฝ่าวิกฤตสงครามโลกครั้งที่ 2 ขึ้นชื่อเรื่องสุนทรพจน์ทรงพลังที่ปลุกขวัญกำลังใจชาวอังกฤษในยามคับขันที่สุด', 'historical', false),
  ('44', '🏰 จอมคนผู้สร้างเมือง (The Master Builder)', 'การสร้างรากฐานที่ยิ่งใหญ่ แต่ต้องแบกรับความกดดันมหาศาล', 'จักรพรรดิออกัสตัส', 'จักรพรรดิองค์แรกของโรม (63 ปีก่อนคริสตกาล-ค.ศ. 14) ผู้ยุติสงครามกลางเมืองและเปิดยุคสันติภาพโรมัน (Pax Romana) ที่ยาวนานกว่า 200 ปี วางรากฐานการปกครองที่ส่งผลถึงยุโรปมาจนถึงปัจจุบัน', 'historical', false),
  ('45', '🧭 นักบุกเบิกผู้ยืดหยุ่น (The Flexible Pioneer)', 'การสร้างรากฐานที่ปรับเปลี่ยนได้ผ่านการเดินทางและการเรียนรู้', 'เลฟ เอริกสัน', 'นักสำรวจชาวไวกิ้ง (ราว ค.ศ. 970-1020) เชื่อกันว่าเป็นชาวยุโรปคนแรกที่เดินทางไปถึงทวีปอเมริกาเหนือ ก่อนโคลัมบัสเกือบ 500 ปี', 'historical', false),
  ('46', '❤️ ผู้พิทักษ์ที่มั่นคง (The Stable Guardian)', 'การดูแลครอบครัวอย่างมั่นคงและรับผิดชอบ เป็นที่พึ่งที่แข็งแกร่ง', 'เฮกเตอร์', 'เจ้าชายและนักรบผู้กล้าหาญที่สุดแห่งเมืองทรอยในมหากาพย์ Iliad ต่อสู้ปกป้องบ้านเมืองจนวาระสุดท้าย ก่อนพ่ายแพ้ต่ออะคิลลีสในการดวลตัวต่อตัวอันโด่งดัง เป็นสัญลักษณ์ของเกียรติยศและความรับผิดชอบ', 'mythological', false),
  ('47', '🧘 ปราชญ์ผู้สันโดษ (The Solitary Sage)', 'การค้นพบความจริงผ่านการศึกษาเชิงลึกและการพัฒนาจิตวิญญาณ', 'เล่าจื๊อ', 'นักปรัชญาจีนโบราณ ผู้ให้กำเนิดแนวคิดเต๋า (Taoism) เน้นการปล่อยวางและอยู่กับธรรมชาติอย่างสมดุล ผลงานสำคัญคือคัมภีร์เต้าเต๋อจิงที่ยังคงมีอิทธิพลถึงปัจจุบัน', 'historical', false),
  ('48', '📈 นักบริหารมือทอง (The Golden Executive)', 'การสร้างความสำเร็จทางธุรกิจที่ยั่งยืนผ่านการจัดการที่มีประสิทธิภาพ', 'ไครซัส', 'กษัตริย์แห่งลิเดีย (ราว 595-546 ปีก่อนคริสตกาล) ขึ้นชื่อเรื่องความร่ำรวยมหาศาลจนเป็นที่มาของสำนวน รวยเท่าไครซัส แต่สุดท้ายพ่ายแพ้สงครามต่อจักรวรรดิเปอร์เซีย', 'historical', false),
  ('49', '🕊️ ผู้ให้ที่หนักแน่น (The Steadfast Giver)', 'การอุทิศตนเพื่อสังคมอย่างมั่นคง แต่อย่างลืมฟังเสียงของตัวเอง', 'ฟลอเรนซ์ ไนติงเกล', 'พยาบาลชาวอังกฤษ (1820-1910) ผู้บุกเบิกการพยาบาลสมัยใหม่ระหว่างสงครามไครเมีย ได้ฉายาสุภาพสตรีแห่งดวงประทีปจากการดูแลทหารบาดเจ็บยามค่ำคืน วางรากฐานวิชาชีพพยาบาลทั่วโลก', 'historical', false),
  ('50', '⛵ นักเดินทางผู้อิสระ (The Independent Voyager)', 'การเริ่มต้นชีวิตใหม่ผ่านการเดินทางและการเปลี่ยนแปลงที่ไร้ขีดจำกัด', 'ซินแบด', 'ตัวละครกะลาสีในนิทานพันหนึ่งราตรี (Arabian Nights) ผจญภัยข้ามทะเลเจ็ดครั้ง เผชิญสัตว์ประหลาดและดินแดนมหัศจรรย์ เป็นตัวแทนของนักผจญภัยผู้กล้าเสี่ยงเพื่อทรัพย์สมบัติและประสบการณ์ใหม่', 'legendary', false),
  ('51', '🦁 ผู้นำนักผจญภัย (The Adventurous Leader)', 'การเป็นผู้นำในสถานการณ์ใหม่ๆ ที่ไม่แน่นอน', 'ฌออากีม มูราต์ (Joachim Murat)', 'แม่ทัพม้าชาวฝรั่งเศส (1767-1815) หนึ่งในนายพลคนสำคัญของนโปเลียน ขึ้นชื่อเรื่องความกล้าบ้าบิ่นในสนามรบ ภายหลังได้เป็นกษัตริย์แห่งเนเปิลส์ก่อนถูกประหารชีวิต', 'historical', false),
  ('52', '🤝 หุ้นส่วนผู้ยืดหยุ่น (The Flexible Partner)', 'การสร้างความสมดุลและความร่วมมือที่ยืดหยุ่นและปรับตัวเก่ง', 'Sun Quan (ซุนกวน)', 'ผู้ปกครองแคว้นง่อในยุคสามก๊กของจีน (ค.ศ. 182-252) ขึ้นชื่อเรื่องความสุขุมรอบคอบและการใช้คนเป็น สามารถรักษาแคว้นง่อให้มั่นคงท่ามกลางสงครามแย่งชิงอำนาจตลอดยุคสามก๊ก', 'historical', false),
  ('53', '🎨 ศิลปินนักเดินทาง (The Traveling Artist)', 'การใช้ความคิดสร้างสรรค์และการสื่อสารที่หลากหลายผ่านการเดินทาง', 'พอล โกแกง', 'จิตรกรชาวฝรั่งเศส (1848-1903) ทิ้งชีวิตนายธนาคารเพื่อตามความฝันด้านศิลปะ เดินทางไปตาฮีตีเพื่อค้นหาแรงบันดาลใจใหม่ สร้างสรรค์ผลงานสีสันจัดจ้านที่แหวกขนบศิลปะยุโรปยุคนั้น', 'historical', false),
  ('54', '🧱 ผู้สร้างที่ยืดหยุ่น (The Flexible Builder)', 'การสร้างรากฐานที่ปรับเปลี่ยนได้ผ่านการทำงานหนักและการปรับตัว', 'เดดาลัส', 'ช่างฝีมือและนักประดิษฐ์ผู้ชาญฉลาดในตำนานกรีก ผู้สร้างเขาวงกตแห่งเกาะครีต และปีกขี้ผึ้งให้ตนเองกับอิคารัสลูกชายบินหนีจากเกาะ เป็นสัญลักษณ์ของอัจฉริยภาพที่มาพร้อมโศกนาฏกรรม', 'mythological', false),
  ('55', '🌪️ นักปฏิวัติ (The Revolutionary)', 'การเปลี่ยนแปลงครั้งยิ่งใหญ่ที่มาพร้อมกับอิสระสูงสุด', 'สปาร์ตาคัส', 'ทาสนักสู้กลาดิเอเตอร์ (ราว 111-71 ปีก่อนคริสตกาล) ผู้นำการก่อกบฏทาสครั้งใหญ่ที่สุดต่อจักรวรรดิโรมัน แม้สุดท้ายพ่ายแพ้ แต่ชื่อของเขากลายเป็นสัญลักษณ์แห่งการต่อสู้เพื่ออิสรภาพตลอดกาล', 'historical', false),
  ('56', '❤️ ผู้ดูแลที่ยืดหยุ่น (The Flexible Caregiver)', 'การดูแลผู้อื่นอย่างมีประสิทธิภาพโดยไม่ทิ้งความเป็นอิสระ', 'มาเรีย มอนเตสซอรี่ (Maria Montessori)', 'แพทย์และนักการศึกษาชาวอิตาลี (1870-1952) ผู้บุกเบิกวิธีการศึกษาแบบมอนเตสซอรี่ที่เน้นให้เด็กเรียนรู้ด้วยตนเองตามธรรมชาติ เป็นหนึ่งในผู้หญิงคนแรกที่จบแพทย์ในอิตาลี', 'historical', false),
  ('57', '🔮 ปราชญ์ผู้ลึกลับ (The Mystic Sage)', 'การค้นพบความจริงทางจิตวิญญาณผ่านการเดินทางและการค้นคว้า', 'นอสตราดามุส', 'หมอและนักพยากรณ์ชาวฝรั่งเศส (1503-1566) ผู้เขียนบทกวีทำนายอนาคตนับพันบทที่คลุมเครือจนตีความได้หลายทาง ชื่อของเขายังถูกอ้างถึงเวลามีเหตุการณ์ใหญ่เกิดขึ้นในโลกจนถึงทุกวันนี้', 'historical', false),
  ('58', '📊 นักลงทุนผู้ปรับตัว (The Adaptive Investor)', 'การสร้างความสำเร็จทางธุรกิจที่ยืดหยุ่นและปรับตัวตามความเสี่ยง', 'Sima Yi (สุมาอี้)', 'ขุนนางและนักยุทธศาสตร์คนสำคัญของแคว้นวุยในยุคสามก๊ก (ค.ศ. 179-251) ขึ้นชื่อเรื่องความอดทนและการวางแผนระยะยาว ท้ายที่สุดตระกูลของเขาได้รวบอำนาจจนสถาปนาราชวงศ์จิ้นได้สำเร็จ', 'historical', false),
  ('59', '🙏 ผู้ให้ผู้รักอิสระ (The Free-spirited Giver)', 'การอุทิศตนเพื่อสังคมอย่างยืดหยุ่นและไม่ยึดติด', 'จอห์นนี่ แอปเปิ้ลซีด', 'ชื่อในตำนานของ John Chapman (1774-1845) ชาวอเมริกันผู้เดินทางปลูกต้นแอปเปิลไปทั่วภาคกลางของสหรัฐฯ กลายเป็นตำนานพื้นบ้านสัญลักษณ์ของผู้ให้และผู้บุกเบิกที่ใจดี', 'legendary', false),
  ('60', '🏡 ผู้พิทักษ์ครอบครัว (The Family Guardian)', 'การอุทิศตนเพื่อความรัก ครอบครัว และการบริการอย่างสมบูรณ์แบบ', 'เทพีฟริกก์', 'ราชินีแห่งเทพในเทพปกรณัมนอร์ส มเหสีของเทพโอดิน เป็นเทพีแห่งการแต่งงาน ความเป็นแม่ และรอบรู้ชะตากรรมของทุกคนแต่ไม่เคยเปิดเผยให้ใครรู้ล่วงหน้า', 'mythological', false),
  ('61', '👑 ผู้นำผู้เปี่ยมรัก (The Loving Leader)', 'การเป็นผู้นำที่ใช้ความรักและความใส่ใจในการริเริ่มโครงการเพื่อสังคม', 'สมเด็จพระราชินีนาถวิกตอเรีย', 'ราชินีแห่งสหราชอาณาจักร (1819-1901) ครองราชย์ยาวนานถึง 63 ปี ยุคสมัยของพระองค์ (Victorian Era) เป็นช่วงที่จักรวรรดิอังกฤษเรืองอำนาจสูงสุดและมีการปฏิวัติอุตสาหกรรมครั้งใหญ่', 'historical', false),
  ('62', '⚖️ ผู้ประสานสัมพันธ์ (The Relationship Mediator)', 'การสร้างความสมดุลและความร่วมมือที่เปี่ยมด้วยความรับผิดชอบ', 'เนวิลล์ เชมเบอร์ลิน (Neville Chamberlain)', 'นายกรัฐมนตรีอังกฤษ (1869-1940) เป็นที่จดจำจากนโยบายประนีประนอมกับฮิตเลอร์ก่อนสงครามโลกครั้งที่ 2 ซึ่งภายหลังถูกมองว่าล้มเหลว ก่อนเชอร์ชิลล์จะเข้ามารับตำแหน่งต่อ', 'historical', false),
  ('63', '🎤 นักสื่อสารผู้ชอบดูแล (The Caring Communicator)', 'การใช้การสื่อสารด้วยความรักเพื่อสร้างสรรค์ผลงานเพื่อสังคม', 'เอวา เปรอง (Eva Perón)', 'สุภาพสตรีหมายเลขหนึ่งของอาร์เจนตินา (1919-1952) หรือที่รู้จักในชื่อเอวิตา จากเด็กยากจนสู่สัญลักษณ์ทางการเมืองที่ประชาชนรักใคร่ ต่อสู้เพื่อสิทธิสตรีและคนยากไร้จนวาระสุดท้ายของชีวิต', 'historical', false),
  ('64', '🏛️ สถาปนิกของครอบครัว (The Family Architect)', 'การสร้างรากฐานที่มั่นคงให้กับครอบครัวผ่านการทำงานหนัก', 'มาร์คัส ออเรลิอุส (Marcus Aurelius)', 'จักรพรรดิโรมัน (ค.ศ. 121-180) และนักปรัชญาสายสโตอิก ผู้เขียนบันทึกส่วนตัว Meditations ที่ยังคงเป็นหนังสือปรัชญาชีวิตที่มีคนอ่านทั่วโลกจนถึงปัจจุบัน', 'historical', false),
  ('65', '✈️ นักเดินทางผู้มีความรับผิดชอบ (The Responsible Traveler)', 'การสร้างสมดุลระหว่างอิสระและความรับผิดชอบผ่านการเดินทาง', 'อิบน์ บัตตูตา (Ibn Battuta)', 'นักเดินทางชาวโมร็อกโก (1304-1369) เดินทางไปทั่วโลกมุสลิมและไกลกว่านั้นรวมระยะทางกว่า 120,000 กิโลเมตร มากกว่ามาร์โคโปโลเสียอีก บันทึกการเดินทางของเขาเป็นหลักฐานสำคัญทางประวัติศาสตร์', 'historical', false),
  ('66', '❤️ ผู้ให้ที่ยิ่งใหญ่ (The Great Giver)', 'การดูแลผู้อื่นอย่างไม่มีเงื่อนไข แต่ต้องเรียนรู้ที่จะรักตนเอง', 'เจ้าแม่กวนอิม (Guan Yin)', 'พระโพธิสัตว์แห่งความเมตตาในพุทธศาสนามหายาน เป็นที่เคารพนับถืออย่างกว้างขวางในเอเชียตะวันออก เชื่อกันว่าท่านสดับฟังเสียงร้องขอความช่วยเหลือของสรรพสัตว์ทุกหนแห่ง', 'religious', false),
  ('67', '🧘 ปราชญ์ผู้มีความรับผิดชอบ (The Responsible Sage)', 'การใช้ปัญญาในการวิเคราะห์ความสัมพันธ์และการพัฒนาจิตวิญญาณ', 'เพลโต (Plato)', 'นักปรัชญากรีกโบราณ (ราว 428-348 ปีก่อนคริสตกาล) ลูกศิษย์ของโสกราตีสและอาจารย์ของอริสโตเติล ก่อตั้งสถาบัน Academy ผลงาน Republic ของเขายังคงเป็นรากฐานของปรัชญาการเมืองตะวันตก', 'historical', false),
  ('68', '🏰 เจ้าแห่งอาณาจักร (The Empire Lord)', 'การสร้างความสำเร็จทางธุรกิจที่ยั่งยืนโดยมีความรับผิดชอบเป็นที่ตั้ง', 'เมเยอร์ อัมเชล ร็อธไชลด์ (Mayer Amschel Rothschild)', 'นายธนาคารชาวเยอรมัน (1744-1812) ผู้ก่อตั้งตระกูลร็อธไชลด์ที่กลายเป็นหนึ่งในตระกูลที่ร่ำรวยและทรงอิทธิพลที่สุดในประวัติศาสตร์การเงินยุโรป ด้วยเครือข่ายธนาคารข้ามประเทศที่บุกเบิกเป็นรายแรกๆ', 'historical', false),
  ('69', '🙏 นักบุญผู้เสียสละ (The Sacrificial Saint)', 'การอุทิศตนเพื่อสังคมอย่างยั่งยืน แต่ต้องระวังความอ่อนไหว', 'พระเยซูแห่งนาซาเร็ธ (Jesus of Nazareth)', 'ศาสดาสำคัญของศาสนาคริสต์ ตามความเชื่อคือพระบุตรของพระเจ้าผู้เสียสละตนเองเพื่อไถ่บาปมวลมนุษย์ คำสอนเรื่องความรักและการให้อภัยของพระองค์มีอิทธิพลต่ออารยธรรมโลกมานานกว่า 2,000 ปี', 'religious', false),
  ('70', '🌌 ผู้แสวงหาสัจธรรม (The Truth Seeker)', 'การค้นพบความจริงที่สมบูรณ์ผ่านการศึกษาเชิงลึกและการพัฒนาจิตวิญญาณ', 'พระพุทธเจ้า', 'เจ้าชายสิทธัตถะผู้สละราชสมบัติเพื่อแสวงหาทางพ้นทุกข์ จนตรัสรู้เป็นพระสัมมาสัมพุทธเจ้าและวางรากฐานพุทธศาสนา คำสอนเรื่องอริยสัจ 4 และมรรค 8 ยังคงเป็นหลักธรรมสำคัญของชาวพุทธทั่วโลก', 'religious', false),
  ('71', '👨‍🔬 ผู้นำนักวิจัย (The Research Leader)', 'การเป็นผู้นำในการค้นคว้าและสร้างนวัตกรรม แต่ต้องควบคุมความหยิ่ง', 'เซอร์ ไอแซก นิวตัน (Isaac Newton)', 'นักวิทยาศาสตร์ชาวอังกฤษ (1643-1727) ผู้ค้นพบกฎแรงโน้มถ่วงและกฎการเคลื่อนที่ 3 ข้อ วางรากฐานฟิสิกส์คลาสสิกที่ใช้อธิบายจักรวาลมานานหลายร้อยปี', 'historical', false),
  ('72', '🔬 นักวิเคราะห์ความสัมพันธ์ (The Relational Analyst)', 'การสร้างความสมดุลและความร่วมมือผ่านการวิเคราะห์อย่างมีเหตุผล', 'บรูตัส (Brutus)', 'นักการเมืองโรมัน (85-42 ปีก่อนคริสตกาล) หนึ่งในผู้ลอบสังหารจูเลียส ซีซาร์ เพื่อนสนิทที่ตนเชื่อว่ากำลังทำลายสาธารณรัฐ วลี Et tu, Brute? กลายเป็นสัญลักษณ์ของการทรยศจากคนใกล้ตัว', 'historical', false),
  ('73', '✍️ นักเขียนเชิงวิเคราะห์ (The Analytical Writer)', 'การใช้ความคิดสร้างสรรค์ในการสื่อสารเชิงลึกและการค้นพบความจริง', 'ฮอร์เฮ หลุยส์ บอร์เกส (Jorge Luis Borges)', 'นักเขียนชาวอาร์เจนตินา (1899-1986) เจ้าของงานเขียนแนวเขาวงกตและปรัชญาที่ผสานความจริงกับจินตนาการ มีอิทธิพลอย่างสูงต่อวรรณกรรมโลกยุคหลัง แม้ตาบอดในบั้นปลายชีวิตแต่ยังคงสร้างสรรค์งานต่อเนื่อง', 'historical', false),
  ('74', '🏗️ สถาปนิกนักวิเคราะห์ (The Analytical Architect)', 'การสร้างรากฐานที่มั่นคงผ่านการทำงานหนักและการค้นคว้าอย่างมีระบบ', 'วิตรูวิอุส (Vitruvius)', 'สถาปนิกและวิศวกรโรมัน (ราวศตวรรษที่ 1 ก่อนคริสตกาล) ผู้เขียนตำรา De Architectura ที่วางหลักการสถาปัตยกรรมไว้ 3 ข้อคือ ความมั่นคง ประโยชน์ใช้สอย และความงาม เป็นแรงบันดาลใจให้ภาพ Vitruvian Man ของดาวินชี', 'historical', false),
  ('75', '🗺️ นักสำรวจผู้ใฝ่รู้ (The Inquisitive Explorer)', 'การเดินทางเพื่อการเรียนรู้และค้นคว้าอย่างอิสระ แต่ต้องสร้างความมั่นคง', 'ชาร์ลส์ ดาร์วิน (Charles Darwin)', 'นักธรรมชาติวิทยาชาวอังกฤษ (1809-1882) ผู้เสนอทฤษฎีวิวัฒนาการผ่านการคัดเลือกโดยธรรมชาติในหนังสือ On the Origin of Species เปลี่ยนความเข้าใจของมนุษยชาติต่อกำเนิดของสิ่งมีชีวิตไปตลอดกาล', 'historical', false),
  ('76', '❤️ ผู้ดูแลผู้เปี่ยมด้วยปัญญา (The Wise Caregiver)', 'การดูแลผู้อื่นอย่างมีเหตุผล แต่ต้องระวังการแบกรับความกังวล', 'ไครอน (Chiron)', 'เซนทอร์ (ครึ่งคนครึ่งม้า) ผู้ทรงปัญญาในเทพปกรณัมกรีก ต่างจากเซนทอร์ตนอื่นที่ดุร้าย ไครอนเป็นครูผู้สอนวีรบุรุษหลายคนรวมถึงอะคิลลีส แม้เป็นอมตะแต่ยอมสละชีวิตเพื่อไถ่โทษให้โพรมีธีอุส', 'mythological', false),
  ('77', '🦉 ปราชญ์ผู้หยั่งรู้ (The Oracle Sage)', 'การเข้าถึงปัญญาญาณที่ลึกซึ้ง แต่ต้องระวังความโดดเดี่ยว', 'เมอร์ลิน (Merlin)', 'พ่อมดในตำนานกษัตริย์อาเธอร์ ที่ปรึกษาผู้ทรงปัญญาและมีพลังเวทมนตร์ เป็นผู้ช่วยให้อาเธอร์ขึ้นครองบัลลังก์และก่อตั้งอาณาจักรคาเมล็อต สัญลักษณ์ของภูมิปัญญาและการมองการณ์ไกล', 'legendary', false),
  ('78', '📈 นักบริหารผู้มีวิสัยทัศน์ (The Visionary Executive)', 'การสร้างความสำเร็จทางธุรกิจที่ยั่งยืนผ่านการวิเคราะห์ที่มีประสิทธิภาพ', 'ตระกูลเมดิชี (Medici Family)', 'ตระกูลนายธนาคารผู้ทรงอิทธิพลที่สุดในฟลอเรนซ์ยุคเรอเนสซองส์ (ศตวรรษที่ 15-18) อุปถัมภ์ศิลปินและนักคิดระดับตำนานจำนวนมาก มีบทบาทสำคัญในการจุดประกายยุคฟื้นฟูศิลปวิทยาของยุโรป', 'historical', false),
  ('79', '🙏 นักบุญผู้มีปัญญา (The Wise Saint)', 'การอุทิศตนเพื่อสังคมอย่างยั่งยืนโดยใช้ปัญญา แต่ต้องระวังความอ่อนไหว', 'Thich Nhat Hanh (ติช นัท ฮันห์)', 'พระภิกษุชาวเวียดนาม (1926-2022) ผู้เผยแพร่แนวคิดการมีสติในปัจจุบันขณะ (mindfulness) ไปทั่วโลกตะวันตก ได้รับการเสนอชื่อชิงรางวัลโนเบลสาขาสันติภาพจากมาร์ติน ลูเธอร์ คิง จูเนียร์', 'religious', false),
  ('80', '🏰 เจ้าแห่งอาณาจักร (The Empire Lord)', 'การสร้างความสำเร็จทางธุรกิจและการจัดการการเงินอย่างสมบูรณ์แบบ', 'มันซา มูซา (Mansa Musa)', 'จักรพรรดิแห่งอาณาจักรมาลีในแอฟริกาตะวันตก (ครองราชย์ราว ค.ศ. 1312-1337) ได้รับการยกย่องว่าอาจร่ำรวยที่สุดในประวัติศาสตร์มนุษยชาติ โด่งดังจากการแจกทองคำมหาศาลระหว่างการแสวงบุญไปเมกกะ', 'historical', false),
  ('81', '👑 จักรพรรดิผู้ทรงอำนาจ (The Powerful Emperor)', 'การเป็นผู้นำที่แข็งแกร่งในการเริ่มต้นธุรกิจและสร้างความสำเร็จ', 'สุลัยมานผู้เกรียงไกร (Suleiman the Magnificent)', 'สุลต่านแห่งจักรวรรดิออตโตมัน (ครองราชย์ 1520-1566) ยุคของพระองค์คือยุคทองของออตโตมันทั้งด้านการทหาร กฎหมาย และศิลปวัฒนธรรม ชาวยุโรปเรียกพระองค์ว่าผู้เกรียงไกรด้วยความเกรงขาม', 'historical', false),
  ('82', '🤝 ทูตผู้ทรงอิทธิพล (The Influential Ambassador)', 'การสร้างความร่วมมือที่ทรงอำนาจเพื่อความสำเร็จที่ยิ่งใหญ่', 'จางเหลียง (Zhang Liang)', 'นักยุทธศาสตร์คนสำคัญในยุคปลายราชวงศ์ฉินของจีน (ราว 250-186 ปีก่อนคริสตกาล) ผู้ช่วยหลิวปังก่อตั้งราชวงศ์ฮั่น ขึ้นชื่อเรื่องสติปัญญาและการวางแผนเบื้องหลังที่ทำให้ได้รับสมญาว่าผู้วางแผนในเต็นท์ ชนะศึกไกลพันลี้', 'historical', false),
  ('83', '📣 ผู้ทรงอิทธิพลทางความคิด (The Influencer)', 'การใช้การสื่อสารและความคิดสร้างสรรค์เพื่อสร้างความสำเร็จและอำนาจ', 'พี.ที. บาร์นัม (P.T. Barnum)', 'นักธุรกิจบันเทิงชาวอเมริกัน (1810-1891) ผู้ก่อตั้งคณะละครสัตว์ Barnum & Bailey Circus ขึ้นชื่อเรื่องกลยุทธ์การตลาดและการโหมโฆษณาเกินจริง เป็นบิดาแห่งวงการโชว์บิสเนสสมัยใหม่', 'historical', false),
  ('84', '🏛️ สถาปนิกผู้ทรงอำนาจ (The Powerful Architect)', 'การสร้างรากฐานที่แข็งแกร่งและทรงอำนาจผ่านการทำงานหนัก', 'อิมโฮเทป (Imhotep)', 'สถาปนิก แพทย์ และนักบวชอียิปต์โบราณ (ราว 2650-2600 ปีก่อนคริสตกาล) ผู้ออกแบบปิรามิดขั้นบันไดแห่งซัคคารา หนึ่งในอาคารหินขนาดใหญ่แห่งแรกของโลก ภายหลังได้รับการเทิดทูนเป็นเทพแห่งการแพทย์', 'historical', false),
  ('85', '🌪️ นักปฏิวัติผู้ทรงอำนาจ (The Powerful Revolutionary)', 'การสร้างอำนาจจากการปรับตัวและการเดินทางเพื่อเรียนรู้', 'นโปเลียน โบนาปาร์ต (Napoleon Bonaparte)', 'จักรพรรดิฝรั่งเศส (1769-1821) นักการทหารอัจฉริยะผู้พิชิตยุโรปเกือบทั้งหมด จากนายทหารชั้นผู้น้อยสู่จักรพรรดิ ก่อนพ่ายแพ้และถูกเนรเทศไปเสียชีวิตที่เกาะเซนต์เฮเลนา', 'historical', false),
  ('86', '❤️ ผู้ดูแลผู้ทรงอิทธิพล (The Influential Caregiver)', 'การดูแลผู้อื่นอย่างมีประสิทธิภาพเพื่อสร้างความสัมพันธ์ที่ดี', 'คอร์เนเลีย แอฟริกานา (Cornelia Africana)', 'สตรีโรมันผู้สูงศักดิ์ (ราว 190-100 ปีก่อนคริสตกาล) ลูกสาวแม่ทัพผู้พิชิตฮันนิบาล ได้รับการยกย่องเป็นแบบอย่างของมารดาโรมันในอุดมคติ ผู้อบรมบุตรชายให้เป็นนักปฏิรูปสังคมคนสำคัญ', 'historical', false),
  ('87', '🦉 ปราชญ์ผู้ทรงอำนาจ (The Powerful Sage)', 'การใช้ปัญญาในการค้นหาความจริงเพื่อสร้างอำนาจจากภายใน', 'จอห์น ดี (John Dee)', 'นักคณิตศาสตร์ นักดาราศาสตร์ และที่ปรึกษาราชสำนักอังกฤษ (1527-1608/9) ในสมัยพระราชินีเอลิซาเบธที่ 1 สนใจทั้งวิทยาศาสตร์และไสยศาสตร์ พยายามติดต่อกับทูตสวรรค์ผ่านพิธีกรรมลึกลับ', 'historical', false),
  ('88', '💎 จักรพรรดิแห่งความมั่งคั่ง (The Emperor of Wealth)', 'การสร้างอาณาจักรธุรกิจที่ต้องใช้อำนาจสมบูรณ์และระวังความโลภ', 'กษัตริย์ไมดาส (King Midas)', 'กษัตริย์ในตำนานกรีกผู้ขอพรให้ทุกสิ่งที่แตะต้องกลายเป็นทองคำ แต่กลับพบว่าแม้แต่อาหารและลูกสาวก็กลายเป็นทองไปด้วย เป็นนิทานสอนใจเรื่องความโลภที่นำมาซึ่งความทุกข์', 'legendary', false),
  ('89', '🙏 ผู้นำผู้เสียสละ (The Sacrificial Leader)', 'การใช้อำนาจเพื่อการให้และการทำงานเพื่อสังคมอย่างยั่งยืน', 'อับราฮัม ลินคอล์น (Abraham Lincoln)', 'ประธานาธิบดีสหรัฐฯ คนที่ 16 (1809-1865) ผู้นำประเทศฝ่าสงครามกลางเมืองและประกาศเลิกทาส จากเด็กยากจนในกระท่อมไม้ซุงสู่ผู้นำที่ยิ่งใหญ่ที่สุดคนหนึ่งของอเมริกา ก่อนถูกลอบสังหารในปีสุดท้ายของสงคราม', 'historical', false),
  ('90', '🕊️ นักบุญผู้ให้ (The Giving Saint)', 'การอุทิศตนเพื่อมนุษยธรรมและการให้ที่ยิ่งใหญ่', 'นักบุญฟรานซิสแห่งอัสซีซี (Saint Francis of Assisi)', 'นักบวชคาทอลิกชาวอิตาลี (1181/82-1226) จากลูกชายพ่อค้าผู้มั่งคั่งสู่ผู้สละทุกสิ่งเพื่อใช้ชีวิตเรียบง่าย รักสัตว์และธรรมชาติ เป็นผู้ก่อตั้งคณะฟรานซิสกัน และเป็นนักบุญอุปถัมภ์สิ่งแวดล้อม', 'religious', false),
  ('91', '👑 ผู้นำผู้เปี่ยมเมตตา (The Compassionate Leader)', 'การเป็นผู้นำที่เสียสละในการเริ่มต้นโครงการเพื่อสังคม', 'พระเจ้าไซรัสมหาราช (Cyrus the Great)', 'ผู้ก่อตั้งจักรวรรดิเปอร์เซีย (ครองราชย์ 559-530 ปีก่อนคริสตกาล) ขึ้นชื่อเรื่องการปกครองที่ให้เกียรติวัฒนธรรมท้องถิ่นของดินแดนที่พิชิตมา และปล่อยชาวยิวที่ถูกจับเป็นเชลยกลับบ้าน', 'historical', false),
  ('92', '🤝 ทูตแห่งสันติภาพ (The Ambassador of Peace)', 'การสร้างความสมดุลและความร่วมมือเพื่อสังคมด้วยความเมตตา', 'อาริสติด บรียอง (Aristide Briand)', 'นักการเมืองฝรั่งเศส (1862-1932) ดำรงตำแหน่งนายกรัฐมนตรีถึง 11 สมัย ได้รับรางวัลโนเบลสาขาสันติภาพจากความพยายามผลักดันความปรองดองระหว่างฝรั่งเศสกับเยอรมนีหลังสงครามโลกครั้งที่ 1', 'historical', false),
  ('93', '🎨 ศิลปินเพื่อสังคม (The Social Artist)', 'การใช้ความคิดสร้างสรรค์และการสื่อสารเพื่อช่วยเหลือและให้กำลังใจ', 'วิกตอร์ อูโก (Victor Hugo)', 'นักเขียนชาวฝรั่งเศส (1802-1885) ผู้ประพันธ์ Les Misérables และ The Hunchback of Notre-Dame งานเขียนของเขามักสะท้อนความอยุติธรรมทางสังคมและเรียกร้องความเห็นอกเห็นใจต่อผู้ยากไร้', 'historical', false),
  ('94', '🏡 ผู้สร้างชุมชน (The Community Builder)', 'การสร้างรากฐานที่มั่นคงให้กับสังคมผ่านการทำงานหนักและการดูแล', 'เจน แอดดัมส์ (Jane Addams)', 'นักปฏิรูปสังคมชาวอเมริกัน (1860-1935) ผู้บุกเบิกงานสังคมสงเคราะห์สมัยใหม่ ก่อตั้ง Hull House เพื่อช่วยเหลือผู้อพยพยากไร้ในชิคาโก เป็นผู้หญิงอเมริกันคนแรกที่ได้รับรางวัลโนเบลสาขาสันติภาพ', 'historical', false),
  ('95', '🦋 นักเดินทางผู้ใจบุญ (The Philanthropic Traveler)', 'การเดินทางเพื่อการเรียนรู้และช่วยเหลือผู้อื่นอย่างอิสระ', 'เดวิด ลิฟวิงสโตน (David Livingstone)', 'นักสำรวจและมิชชันนารีชาวสก็อต (1813-1873) ผู้สำรวจแอฟริกากลางอย่างกว้างขวาง ค้นพบน้ำตกวิกตอเรีย ต่อต้านการค้าทาส เรื่องราวการตามหาตัวเขาที่หายสาบสูญกลายเป็นตำนาน Dr. Livingstone, I presume?', 'historical', false),
  ('96', '❤️ ผู้ดูแลผู้เสียสละ (The Sacrificial Caregiver)', 'การดูแลผู้อื่นอย่างมีประสิทธิภาพ แต่ต้องระวังการแบกรับภาระ', 'นักบุญเวโรนิกา (Saint Veronica)', 'ตามตำนานคริสต์ศาสนา (ไม่ปรากฏในพระคัมภีร์ไบเบิลหลัก) เป็นสตรีผู้เช็ดพระพักตร์พระเยซูระหว่างทางแบกกางเขน แล้วภาพพระพักตร์ปรากฏบนผ้าที่ใช้เช็ดอย่างอัศจรรย์ เป็นสัญลักษณ์ของความเมตตากรุณา', 'religious', false),
  ('97', '🧠 นักจิตวิทยาเพื่อสังคม (The Social Psychologist)', 'การใช้ปัญญาในการค้นหาความจริงทางจิตวิญญาณเพื่อช่วยเหลือผู้อื่น', 'คาร์ล โรเจอร์ส (Carl Rogers)', 'นักจิตวิทยาชาวอเมริกัน (1902-1987) ผู้บุกเบิกแนวคิดจิตบำบัดแบบยึดผู้รับบริการเป็นศูนย์กลาง (person-centered therapy) เน้นการรับฟังอย่างเข้าใจและไม่ตัดสิน มีอิทธิพลอย่างสูงต่อวงการจิตวิทยาการปรึกษาสมัยใหม่', 'historical', false),
  ('98', '📈 ผู้จัดการเพื่อสังคม (The Social Manager)', 'การสร้างความสำเร็จทางธุรกิจที่ยั่งยืนโดยมีเป้าหมายเพื่อสังคม', 'โรเบิร์ต โอเวน (Robert Owen)', 'นักอุตสาหกรรมและนักปฏิรูปสังคมชาวเวลส์ (1771-1858) ผู้บุกเบิกแนวคิดสังคมนิยมยุคแรก ปรับปรุงสภาพความเป็นอยู่ของคนงานในโรงงาน และก่อตั้งชุมชนทดลองเพื่อความเท่าเทียม', 'historical', false),
  ('99', '🌍 ผู้อุทิศตนเพื่อโลก (The World Philanthropist)', 'การให้และการเสียสละที่ยิ่งใหญ่เพื่อมวลมนุษยชาติ', 'โพรมีธีอุส (Prometheus)', 'ไททันในเทพปกรณัมกรีกผู้ขโมยไฟจากเทพเจ้ามามอบให้มนุษยชาติ ฝ่าฝืนคำสั่งเทพซุส ถูกลงโทษให้ถูกล่ามโซ่ไว้บนภูเขาให้นกอินทรีจิกกินตับทุกวันชั่วนิรันดร์ เป็นสัญลักษณ์ของการเสียสละเพื่อผู้อื่น', 'mythological', false)
INSERT INTO dream_symbols (category, dream_object, chinese_char, kangxi_strokes, element, meaning_keyword, source) VALUES
  ('ครอบครัว (Family)', 'พ่อ / บิดา', '父', 4, 'ไฟ', 'อำนาจ, ผู้นำครอบครัว, การปกป้อง, ความรับผิดชอบ, ความสำเร็จ', 'original_457'),
  ('ครอบครัว', 'แม่ / มารดา', '母', 5, 'ดิน', 'ความรักความผูกพัน, การดูแลเอาใจใส่, บ้าน, ความอุดมสมบูรณ์', 'original_457'),
  ('ครอบครัว', 'ลูก / เด็กทารก', '子', 3, 'ไม้', 'การเริ่มต้นใหม่, ความบริสุทธิ์, ภาระที่น่ายินดี, โชคลาภเล็กๆ', 'original_457'),
  ('ครอบครัว', 'พี่ชาย / พี่สาว', '兄', 5, 'ไม้', 'ที่ปรึกษา, การช่วยเหลือ, มิตรภาพ, ความขัดแย้ง (ถ้าทะเลาะ)', 'original_457'),
  ('ครอบครัว', 'น้องชาย / น้องสาว', '弟', 7, 'ไม้', 'ความห่วงใย, ภาระที่ต้องดูแล, ความสนุกสนาน, ความวุ่นวาย', 'original_457'),
  ('ครอบครัว', 'ปู่ย่าตายาย', '祖', 10, 'ดิน', 'รากเหง้า, มรดก, ความคุ้มครอง, สุขภาพ, เรื่องเก่าๆ', 'original_457'),
  ('ครอบครัว', 'ญาติพี่น้อง', '親', 16, 'ไม้', 'ความสามัคคี, ปัญหาเรื่องเงิน, การรวมตัว, ข่าวสารในวงศ์ตระกูล', 'original_457'),
  ('ความรัก (Romance)', 'แฟน / คนรักปัจจุบัน', '愛', 13, 'ไฟ', 'ความสัมพันธ์, ความหึงหวง, การเปลี่ยนแปลง, ความสุข', 'original_457'),
  ('ความรัก', 'แฟนเก่า', '舊', 18, 'น้ำ', 'เรื่องในอดีต, ปมในใจ, การเปรียบเทียบ, สิ่งที่ยังค้างคา', 'original_457'),
  ('ความรัก', 'คนแอบชอบ', '戀', 23, 'ไฟ', 'ความหวัง, จินตนาการ, ความไม่แน่นอน, แรงบันดาลใจ', 'original_457'),
  ('ความรัก', 'สามี / ภรรยา', '偶', 11, 'ดิน', 'ความมั่นคง, หุ้นส่วนชีวิต, หน้าที่ความรับผิดชอบ, ความอดทน', 'original_457'),
  ('ความรัก', 'ชู้ / มือที่สาม', '姦', 9, 'น้ำ', 'ความลับ, ปัญหาชู้สาว, การทรยศ, ความตื่นเต้นที่อันตราย', 'original_457'),
  ('สถานะทางสังคม (Roles)', 'เพื่อน / มิตรสหาย', '友', 4, 'ไม้', 'การสนับสนุน, สังคมใหม่, ข่าวสาร, การร่วมมือ', 'original_457'),
  ('สถานะทางสังคม', 'ศัตรู / คู่แข่ง', '敵', 15, 'ทอง', 'อุปสรรค, การแข่งขัน, แรงผลักดัน, ความระแวง', 'original_457'),
  ('สถานะทางสังคม', 'เจ้านาย / หัวหน้า', '長', 8, 'ไฟ', 'อำนาจ, ความกดดัน, การเลื่อนขั้น, การถูกประเมิน', 'original_457'),
  ('สถานะทางสังคม', 'ลูกน้อง / บริวาร', '僕', 14, 'ดิน', 'ภาระความรับผิดชอบ, การช่วยเหลือ, ปัญหาจุกจิก, ความจงรักภักดี', 'original_457'),
  ('สถานะทางสังคม', 'ครู / อาจารย์', '師', 10, 'ไม้', 'ความรู้, คำแนะนำ, การชี้นำ, การแก้ปัญหา', 'original_457'),
  ('สถานะทางสังคม', 'พระ / นักบวช', '僧', 14, 'ทอง', 'ศีลธรรม, การปล่อยวาง, ความสงบสุข, การแก้กรรม', 'original_457'),
  ('สถานะทางสังคม', 'หมอ / พยาบาล', '醫', 18, 'ทอง', 'ปัญหาสุขภาพ, การรักษาเยียวยา, ความกังวล, การดูแล', 'original_457'),
  ('สถานะทางสังคม', 'ตำรวจ', '警', 20, 'ทอง', 'กฎระเบียบ, ความผิด, เรื่องร้อนใจ, การตรวจสอบ', 'original_457'),
  ('สถานะทางสังคม', 'ทหาร', '軍', 9, 'ไฟ', 'ความเข้มงวด, ระเบียบวินัย, การต่อสู้, ความแข็งแกร่ง', 'original_457'),
  ('สถานะทางสังคม', 'กษัตริย์ / ราชินี', '王', 4, 'ดิน', 'ยศถาบรรดาศักดิ์, ความสำเร็จสูงสุด, ผู้ใหญ่เมตตา, บารมี', 'original_457'),
  ('สถานะทางสังคม', 'คนตาย / ศพ', '屍', 9, 'ดิน', 'การสิ้นสุดปัญหา, โชคลาภก้อนใหญ่ (ลาภลอย), การเริ่มต้นใหม่, หนี้สิน', 'original_457'),
  ('สถานะทางสังคม', 'ขอทาน', '乞', 3, 'น้ำ', 'ความสูญเสีย, ความเมตตา, การเตือนสติเรื่องเงิน, โชคลาภเล็กน้อย', 'original_457'),
  ('สถานะทางสังคม', 'โจร / ขโมย', '盜', 12, 'น้ำ', 'ความลับ, การสูญเสียของรัก, ความไม่ปลอดภัย, (บางตำราว่าทุกข์ลาภ)', 'original_457'),
  ('สถานะทางสังคม', 'ดารา / คนดัง', '名', 6, 'ไฟ', 'ชื่อเสียง, ความทะเยอทะยาน, ภาพลักษณ์, ข่าวลือ', 'original_457'),
  ('สถานะทางสังคม', 'คนท้อง', '孕', 5, 'ไม้', 'การรอคอยผลสำเร็จ, ภาระใหม่, ความเจริญเติบโต, โชคลาภ', 'original_457'),
  ('สถานะทางสังคม', 'คนแก่ / ผู้สูงอายุ', '老', 6, 'ดิน', 'ประสบการณ์, ความเสื่อมถอย, ภูมิปัญญา, สุขภาพ', 'original_457'),
  ('แมลงนำโชค/ความหมายดี', 'ผึ้ง / ต่อ / แตน', '蜂', 13, 'ทอง', 'ความขยัน, การทำงานเป็นทีม, โชคลาภ (น้ำผึ้ง), ผลกำไรที่หอมหวาน', 'original_457'),
  ('แมลงนำโชค', 'ผีเสื้อ', '蝶', 15, 'ไม้', 'การเปลี่ยนแปลงที่งดงาม, ความรัก, จิตวิญญาณบรรพบุรุษ, ความสุข', 'original_457'),
  ('แมลงนำโชค', 'เต่าทอง', '甲', 5, 'ทอง', 'ความโชคดีเรื่องเงิน, ข่าวดี, การป้องกันตัว, ความน่ารักเอ็นดู', 'original_457'),
  ('แมลงนำโชค', 'หิ่งห้อย', '螢', 16, 'ไฟ', 'ความหวังริบหรี่แต่มีจริง, แสงสว่างนำทาง, ความโรแมนติก, ปัญญา', 'original_457'),
  ('แมลงนำโชค', 'จักจั่น', '蟬', 18, 'ทอง', 'การเกิดใหม่, ความเป็นอมตะ, ชื่อเสียงโด่งดัง, การลอกคราบ (เปลี่ยนแปลงตัวเอง)', 'original_457'),
  ('แมลงนำโชค', 'จิ้งหรีด', '蟋', 17, 'ไม้', 'ความสุขในครัวเรือน, ฤดูกาลเปลี่ยน, ข่าวดี, การเตือนภัย', 'original_457'),
  ('แมลงนำโชค', 'ตั๊กแตนตำข้าว', '螳', 17, 'ไม้', 'ความนิ่งสงบสยบเคลื่อนไหว, ความอดทนรอจังหวะ, ผู้หญิงมีอำนาจ', 'original_457'),
