INSERT INTO personal_year_guidance (personal_year_number, theme, prediction_overview, caution, opportunity, action_advice) VALUES
  (1, 'การเริ่มต้นใหม่', 'ปีแห่งการปลูกเมล็ดพันธุ์ใหม่ เหมาะแก่การเริ่มงานใหม่ โปรเจกต์ใหม่ หรือเปลี่ยนวิถีชีวิต เป็นช่วงเวลาที่พลังงานพุ่งพล่าน', 'ความใจร้อนและการใช้อำนาจเกินขอบเขต ความมั่นใจที่มากเกินไปจนประมาท', 'โอกาสในการเป็นผู้นำ การได้รับตำแหน่งใหม่ หรือการริเริ่มธุรกิจของตัวเอง', 'กล้าคิดกล้าทำ อย่ารอช้า แต่ต้องวางแผนให้รอบคอบก่อนลุยเต็มที่'),
  (2, 'สร้างสายสัมพันธ์', 'ปีแห่งการรอคอยและความร่วมมือ ไม่ควรฉายเดี่ยว เป็นปีที่ต้องอาศัยทีมเวิร์คและการเจรจาต่อรอง', 'ความอ่อนไหวทางอารมณ์ ความขัดแย้งส่วนตัว และความลังเลใจ', 'การได้คู่ครอง หุ้นส่วนทางธุรกิจ หรือกัลยาณมิตรที่ดีเข้ามาช่วยเหลือ', 'ฝึกความอดทน ประนีประนอม รับฟังผู้อื่น และสร้างคอนเนกชันที่ดี'),
  (3, 'การแสดงออก', 'ปีแห่งความสนุกสนาน การเข้าสังคม และการใช้ความคิดสร้างสรรค์ บรรยากาศรอบตัวจะดูสดใสและมีชีวิตชีวา', 'การใช้จ่ายฟุ่มเฟือย ขาดสมาธิในการทำงาน และคำพูดที่อาจพลั้งปากสร้างศัตรู', 'ชื่อเสียง การเดินทางท่องเที่ยว การได้รับการยอมรับในวงสังคม', 'ออกไปพบปะผู้คน พรีเซนต์งาน ดูแลภาพลักษณ์ให้ดูดีเสมอ'),
  (4, 'สร้างรากฐาน', 'ปีแห่งการทำงานหนัก การวางระบบ และการสร้างความมั่นคงระยะยาว อาจรู้สึกเหนื่อยและหนักกว่าปีก่อนๆ', 'ความเครียดสะสม ปัญหาสุขภาพจากการทำงานหนัก และความเข้มงวดเกินไป', 'ความสำเร็จที่จับต้องได้ การสร้างสินทรัพย์ เช่น บ้าน รถ หรือความมั่นคงทางการงาน', 'จัดระเบียบชีวิต การเงิน และแบ่งเวลาดูแลสุขภาพให้สมดุล'),
  (5, 'การเปลี่ยนแปลง', 'ปีแห่งอิสระ การเปลี่ยนแปลงฉับพลัน และการเดินทางแสวงหาประสบการณ์ใหม่ๆ ชีวิตจะมีสีสันและคาดเดายาก', 'ความเสี่ยง อุบัติเหตุจากการเดินทาง และความไม่แน่นอนของสถานการณ์', 'โอกาสใหม่ที่ไม่คาดคิด การขยายโลกทัศน์ และการได้ลองทำสิ่งที่ไม่เคยทำ', 'ทำใจให้ยืดหยุ่น พร้อมรับสิ่งใหม่ มีสติ และอย่าประมาทในการใช้ชีวิต'),
  (6, 'ความรักและครอบครัว', 'ปีแห่งความรับผิดชอบต่อครอบครัว บ้าน และความรัก เป็นช่วงเวลาของการดูแลใส่ใจคนใกล้ชิด', 'ภาระหนี้สินในครอบครัว หรือปัญหาจุกจิกกวนใจของญาติพี่น้อง', 'ความรักสุกงอม การแต่งงาน การมีสมาชิกใหม่ หรือการปรับปรุงบ้านให้น่าอยู่', 'ดูแลคนใกล้ชิด ตกแต่งบ้านให้สวยงาม และใส่ใจความรู้สึกคนรอบข้างให้มาก'),
  (7, 'ค้นหาตนเอง', 'ปีแห่งการปลีกวิเวก เพื่อศึกษาหาความรู้และทบทวนเป้าหมายชีวิต เหมาะกับการเรียนต่อหรือปฏิบัติธรรม', 'ความรู้สึกโดดเดี่ยว ซึมเศร้า หรือความสัมพันธ์ที่ดูห่างเหินไปบ้าง', 'การตื่นรู้ทางปัญญา การค้นพบทางจิตวิญญาณ และการได้คำตอบสำคัญของชีวิต', 'หาเวลาทำสมาธิ ศึกษาศาสตร์ลึกลับ อ่านหนังสือพัฒนาตนเอง หรือเรียนต่อ'),
  (8, 'ความสำเร็จและการเงิน', 'ปีแห่งการกอบโกย ผลตอบแทนจากการลงทุน และการใช้อำนาจบริหาร เป็นปีที่การเงินสะพัดที่สุด', 'ความโลภที่ขาดสติ คดีความทางธุรกิจ หรือการถูกตรวจสอบบัญชี', 'การเลื่อนตำแหน่ง ขยายธุรกิจขนาดใหญ่ และความมั่งคั่งร่ำรวย', 'บริหารการเงินและอำนาจอย่างมีธรรมาภิบาล กล้าลงทุนแต่ต้องรอบคอบ'),
  (9, 'การสิ้นสุดและเสียสละ', 'ปีแห่งการจบสิ่งเก่าเพื่อเริ่มสิ่งใหม่ การเคลียร์ของเก่า และการทำบุญเพื่อเสริมบารมี', 'การสูญเสียของรัก การจากลา หรือความรู้สึกว่างเปล่าชั่วขณะ', 'ได้ล้างไพ่ชีวิต ปลดหนี้สินทางใจและทางกาย เตรียมพร้อมสำหรับรอบใหม่ในปีหน้า', 'บริจาคสิ่งของที่ไม่ใช้ ปล่อยวางอดีต ทำจิตใจให้ผ่องใส และช่วยเหลือสังคม'),
  (11, 'จิตวิญญาณและลางสังหรณ์', 'ปีที่มีพลังพิเศษ สัญชาตญาณแรงกล้า และมีมุมมองที่ลึกซึ้งกว่าปกติ (Master Year)', 'ความเครียดทางประสาท ความวิตกกังวลสูง และความคาดหวังในอุดมคติ', 'การเป็นผู้นำทางจิตวิญญาณ ผู้สร้างแรงบันดาลใจ หรือผู้ค้นพบนวัตกรรม', 'เชื่อในลางสังหรณ์ของตนเอง ใช้เซ้นส์นำทาง และใช้ความสามารถช่วยเหลือผู้อื่น'),
  (22, 'การสร้างสรรค์ที่ยิ่งใหญ่', 'ปีแห่งการเปลี่ยนความฝันให้เป็นความจริงในระดับมหภาค (Master Year)', 'ความกดดันมหาศาล และการแบกรับภาระที่หนักอึ้งเกินตัว', 'ความสำเร็จระดับนานาชาติ โครงการขนาดใหญ่ที่เปลี่ยนโลกหรือสังคมได้', 'คิดให้ใหญ่ วางแผนให้ไกล หาคนเก่งมาช่วย และลงมือทำให้เป็นรูปธรรม'),
  (33, 'เมตตาธรรมค้ำจุนโลก', 'ปีแห่งการเสียสละขั้นสูงและการเป็น "ผู้ให้" อย่างแท้จริง (Master Year)', 'การถูกเอาเปรียบจากความใจดี หรือเสียสละจนตัวเองและครอบครัวเดือดร้อน', 'การได้รับการยกย่องสรรเสริญ ความสุขทางใจ และบารมีที่เพิ่มพูน', 'ช่วยเหลือสังคมโดยไม่หวังผลตอบแทน แต่ต้องรู้จักประมาณตนและรักษาสมดุล')
INSERT INTO wellness_activities (element, internal_name, internal_tradition, internal_how_to, internal_research, external_name, external_category, external_how_to, external_research, combo_routine, best_time, time_reason) VALUES
  ('Fire', 'Kapalabhati (ลมไฟ)', 'โยคะ/Pranayama', 'หายใจออกแรงๆ เร็วๆ ทางจมูก ปล่อยให้หายใจเข้าเป็นไปเอง ทำต่อเนื่อง 20-30 ครั้งต่อรอบ', 'Nivethitha et al. 2017, Ancient Science of Life', 'วิ่ง หรือ ปีนเขา/hiking ระดับหนัก', 'movement', 'เคลื่อนไหวต่อเนื่อง 20-30 นาที ให้หัวใจเต้นเร็วขึ้นชัดเจน', 'Niedermeier et al. — hiking 30 นาที ลดฮอร์โมนความเครียดได้ถึง 28%', 'ตอนเช้า: Kapalabhati 5 นาทีก่อนออกจากบ้าน แล้วตามด้วยวิ่ง/เดินเร็ว 20 นาที — ใช้จังหวะหายใจที่กระตุ้นแล้วต่อด้วยการเคลื่อนไหวจริง', 'เช้า', 'ออกกำลังกายตอนเช้าช่วย advance circadian phase และลดคอร์ติซอลตอนตื่นในระยะยาว (PMC systematic review)'),
  ('Water', 'Bhramari (หายใจผึ้ง)', 'โยคะ/Pranayama', 'หายใจเข้าลึกๆ หายใจออกพร้อมทำเสียงฮัมต่อเนื่อง ทำ 5-10 รอบ', 'ลด cortisol, calming (เชื่อมกับ Nivethitha et al. 2017)', 'เดินเบาๆในธรรมชาติ / ฟังเพลงบรรเลงสงบ', 'nature/music', 'เดินช้าๆ 15-20 นาทีในที่มีต้นไม้ หรือฟังเพลงบรรเลงแบบตั้งใจฟัง (ไม่ใช่เปิดคลอ)', 'Bratman/Stanford — เดินธรรมชาติลดการทำงาน subgenual PFC (จุดคิดวนซ้ำ)', 'ก่อนนอน: Bhramari 5 รอบบนเตียง แล้วฟังเพลงบรรเลงเบาๆ 10 นาทีก่อนหลับ', 'ก่อนนอน', 'งานวิจัยชัดเจนว่ากิจกรรมสงบก่อนนอนช่วยการนอนหลับ ต่างจากออกกำลังกายหนักที่รบกวนการนอน'),
  ('Earth', 'Dan Tian breathing (หายใจจากจุดต่ำท้อง)', 'ไทเก๊ก/ชี่กง', 'วางมือที่ท้องใต้สะดือ หายใจให้ท้องพองยุบ รู้สึกถึงจุดศูนย์กลางร่างกาย 5-10 นาที', 'Jahnke et al. 2010 — รีวิว 66 งานวิจัย Qigong/Tai Chi', 'เดินป่าจังหวะกลาง / วาดภาพ-ปั้นดิน', 'movement/art', 'เดินในจังหวะสม่ำเสมอ ไม่เร่งรีบ 20-30 นาที หรือทำงานศิลปะที่ได้สัมผัสวัสดุจริง (ดินน้ำมัน/สีน้ำ)', 'Art therapy ลดคอร์ติซอลจริง (systematic review, ยอมรับตั้งแต่ 1940s)', 'บ่าย: Dan Tian breathing 5 นาที แล้วเดินเล่นจังหวะช้าๆ 20 นาที — เน้นความรู้สึก ''ปักหลัก'' ตลอดกิจกรรม', 'เช้าหรือบ่าย', 'กิจกรรม grounding เหมาะเป็นช่วงเปลี่ยนผ่าน ไม่จำเป็นต้องผูกกับ circadian phase เท่าธาตุไฟ/น้ำ'),
  ('Wood', 'เมตตาภาวนา (Loving-Kindness Meditation)', 'พุทธ', 'นั่งสบายๆ ระลึกความรู้สึกดีต่อตนเอง แล้วขยายไปยังคนใกล้ตัว 10-15 นาที', 'Lutz et al. 2008, PNAS — กระตุ้น insula + ACC', 'วาดภาพ/เขียนสร้างสรรค์ หรือเล่นดนตรี (ไม่ใช่แค่ฟัง)', 'art/music', 'ให้เวลา 20-30 นาทีทำงานสร้างสรรค์แบบไม่มีเป้าหมายตายตัว ปล่อยให้ไหลไปเรื่อยๆ', 'Music therapy meta-analysis 2022 — ผลบวกต่อ stress-related outcomes', 'กลางวัน: เมตตาภาวนาสั้นๆ 5 นาที แล้วต่อด้วยกิจกรรมสร้างสรรค์อิสระ 20 นาที ไม่ตั้งเป้าผลงาน', 'กลางวัน', 'ธาตุไม้เชื่อมกับการเติบโต/ขยาย เหมาะกับช่วงที่พลังงานกำลังขึ้น ไม่ใช่ต้นหรือปลายวัน'),
  ('Metal', 'Box Breathing (Sama Vritti) / วิปัสสนา', 'โยคะ + พุทธ', 'หายใจเข้า 4 วินาที กลั้น 4 วินาที หายใจออก 4 วินาที กลั้น 4 วินาที ทำ 5-10 รอบ', 'เสถียรภาพระบบประสาทอัตโนมัติ (ANS) — เชื่อมกับหลัก Box Breathing มาตรฐาน', 'งานฝีมือละเอียด/ถ่ายภาพ หรือฟังดนตรีคลาสสิก/มีโครงสร้างชัด', 'art/music', 'เลือกงานที่ต้องใช้ความละเอียด/มีขั้นตอนชัดเจน 20-30 นาที', 'Frontiers 2024 — creative arts เชื่อมกับ medial rPFC ด้าน emotion regulation', 'เย็น: Box Breathing 5 นาทีก่อนเริ่มงานฝีมือ/ถ่ายภาพ 20-30 นาที — เน้นความคมชัด มีโครงสร้าง', 'เย็น', 'ธาตุทองเชื่อมกับความชัดเจน/ปล่อยวาง เหมาะเป็นช่วงสรุปวัน ก่อนเข้าสู่ธาตุน้ำตอนกลางคืน')
